#include <entropy/module_abi.h>
#include <entropy/src_abi.h>
#include <Windows.h>
#include <array>
#include <vector>
#include <cmath>
#include <cstring>
#include <iostream>
#include <stdexcept>
#include <algorithm>
void check(bool b){if(!b)throw std::runtime_error("ABI/process failure");}
struct Result {std::vector<double> audio;unsigned first=0,maxBurst=0,maxGap=0;};
Result render(const char* path,unsigned engine,unsigned rate,unsigned channels){HMODULE lib=LoadLibraryA(path);check(lib);auto get=reinterpret_cast<EntropyModuleGetApiFn>(GetProcAddress(lib,ENTROPY_MODULE_GET_API_SYMBOL));check(get);EntropyModuleApiV1 common{};common.struct_size=sizeof(common);check(get(ENTROPY_MODULE_ABI_VERSION,&common)==ENTROPY_OK);EntropySrcApiV1 api{};api.struct_size=sizeof(api);check(common.query_extension(ENTROPY_SRC_EXTENSION_ID,ENTROPY_SRC_EXTENSION_VERSION,&api,sizeof(api))==ENTROPY_OK);EntropyHostServices host{};host.struct_size=sizeof(host);host.abi_version=ENTROPY_MODULE_ABI_VERSION;EntropyModuleHandle handle{};check(common.create(&host,&handle)==ENTROPY_OK);EntropyPrepareInfo p{};p.struct_size=sizeof(p);p.sample_rate=192000;p.maximum_frames=256;p.input_channels=p.output_channels=channels;check(common.prepare(handle,&p)==ENTROPY_OK);EntropySrcConfig cfg{};cfg.struct_size=sizeof(cfg);cfg.engine=engine;cfg.source_rate=rate;cfg.destination_rate=192000;cfg.channels=channels;cfg.maximum_input_frames=256;check(api.configure(handle,&cfg)==ENTROPY_OK);std::vector<std::vector<double>> input(channels,std::vector<double>(256)),output(channels,std::vector<double>(cfg.required_output_capacity));std::vector<const double*> ip(channels);std::vector<double*> op(channels);for(unsigned c=0;c<channels;++c){ip[c]=input[c].data();op[c]=output[c].data();}Result result;unsigned gap=0;for(unsigned n=0;n<2000;++n){for(unsigned i=0;i<256;++i){auto frame=n*256+i;for(unsigned c=0;c<channels;++c) input[c][i]=0.3/(c+1)*sin(6.283185307179586*(997+c*311)*frame/rate)+((frame%127)-63.0)/131072;}EntropySrcBlockF64 b{};b.struct_size=sizeof(b);b.channels=channels;b.input_frames=256;b.output_capacity=cfg.required_output_capacity;b.inputs=ip.data();b.outputs=op.data();check(api.process(handle,&b)==ENTROPY_OK&&b.consumed_frames==256);if(b.produced_frames){if(result.first)result.maxGap=std::max(result.maxGap,gap);else result.first=(n+1)*256;gap=0;result.maxBurst=std::max(result.maxBurst,b.produced_frames);for(unsigned i=0;i<b.produced_frames;++i)for(unsigned c=0;c<channels;++c)result.audio.push_back(output[c][i]);}else ++gap;}common.destroy(handle);FreeLibrary(lib);return result;}
int main(int argc,char** argv){if(argc!=3)return 2;try{for(unsigned channels:{2u,8u})for(unsigned engine:{0u})for(unsigned rate:{44100u,48000u,88200u,96000u,176400u,192000u}){auto a=render(argv[1],engine,rate,channels),b=render(argv[2],engine,rate,channels);auto count=std::min(a.audio.size(),b.audio.size());unsigned mismatches=0;double error=0;for(size_t i=0;i<count;++i){if(memcmp(&a.audio[i],&b.audio[i],8))++mismatches;error=std::max(error,std::abs(a.audio[i]-b.audio[i]));}std::cout<<"channels="<<channels<<" engine="<<engine<<" rate="<<rate<<" frames_old="<<a.audio.size()/channels<<" frames_new="<<b.audio.size()/channels<<" mismatches="<<mismatches<<" max_error="<<error<<" first_input_old="<<a.first<<" first_input_new="<<b.first<<" burst_old="<<a.maxBurst<<" burst_new="<<b.maxBurst<<" zero_gap_old="<<a.maxGap<<" zero_gap_new="<<b.maxGap<<"\n";if(engine==0&&(mismatches||a.audio.size()!=b.audio.size()))return 1;}return 0;}catch(std::exception& e){std::cerr<<e.what();return 1;}}
